def flw_callback():
    sig     = request.headers.get("verif-hash", "")
    payload = request.get_data()
    expected = hmac.new(
        Config.FLUTTERWAVE_SECRET.encode(),
        payload,
        hashlib.sha256
    ).hexdigest()
    if not hmac.compare_digest(sig, expected):
        abort(400, "Invalid signature")
    data = request.json.get("data", {})
    tx   = data.get("id")
    # Verify the transaction with Flutterwave's API
    resp = (
        requests
        .get(
            f"https://api.flutterwave.com/v3/transactions/{tx}/verify",
            headers={"Authorization": f"Bearer {Config.FLUTTERWAVE_SECRET}"}
        )
        .json()
        .get("data", {})
    )
    if resp.get("status") == "successful":
        dep = deposits.find_one({"flutterwave_txn_id": tx})
        if dep and dep["status"] == "pending":
            deposits.update_one(
                {"flutterwave_txn_id": tx},
                {"$set": {"status": "completed"}}
            )
            users.update_one(
                {"telegram_id": dep["user_id"]},
                {"$inc": {"balance": dep["amount"]}}
            )
    return jsonify(status="ok")
