class VunaInferenceAPI:
    def __init__(self, model_path: str = "/content/drive/MyDrive/vuna_model/llama-3.1-8b-vuna"):
        self.model_path = model_path
        self.model = None
        self.tokenizer = None
        self.pipe = None
        self.app = Flask(__name__)
        CORS(self.app)
        self.setup_routes()
    def setup_routes(self):
        """Setup Flask routes."""
        @self.app.route('/health', methods=['GET'])
        def health_check():
            """Health check endpoint."""
            return jsonify({
                'status': 'healthy',
                'model_loaded': self.model is not None,
                'timestamp': time.time()
            })
        @self.app.route('/analyze', methods=['POST'])
        def analyze_feedback():
            """Main analysis endpoint - compatible with current Gemini interface."""
            try:
                data = request.get_json()
                if not data or 'prompt' not in data:
                    return jsonify({
                        'error': 'Prompt is required',
                        'response': 'Please provide a prompt for analysis.'
                    }), 400
                user_prompt = data['prompt']
                # Add feedback context if provided
                feedback_context = data.get('feedback_context', {})
                # Build the full prompt with Quaero persona
                full_prompt = self.build_quaero_prompt(user_prompt, feedback_context)
                # Generate response
                response = self.generate_response(full_prompt)
                # Return in same format as Gemini API
                return jsonify({
                    'response': response,
                    'context': {
                        'model': 'vuna-custom-llama-3.1-8b',
                        'total_analyzed': feedback_context.get('total_feedback', 0),
                        'scopes': list(feedback_context.get('by_scope', {}).keys())
                    }
                })
            except Exception as e:
                logger.error(f"Error in analyze_feedback: {e}")
                return jsonify({
                    'error': str(e),
                    'response': f'I encountered an issue processing your request. Error: {str(e)}'
                }), 500
        @self.app.route('/analyze_batch', methods=['POST'])
        def analyze_batch():
            """Batch analysis endpoint for multiple feedback items."""
            try:
                data = request.get_json()
                if not data or 'feedback_items' not in data:
                    return jsonify({'error': 'feedback_items array is required'}), 400
                feedback_items = data['feedback_items']
                analysis_type = data.get('analysis_type', 'summary')
                results = []
                for item in feedback_items:
                    prompt = self.build_batch_prompt(item, analysis_type)
                    response = self.generate_response(prompt)
                    results.append({
                        'id': item.get('id'),
                        'analysis': response
                    })
                return jsonify({
                    'results': results,
                    'total_processed': len(results)
                })
            except Exception as e:
                logger.error(f"Error in analyze_batch: {e}")
                return jsonify({'error': str(e)}), 500
        @self.app.route('/classify', methods=['POST'])
        def classify_feedback():
            """Classification endpoint for priority/sentiment analysis."""
            try:
                data = request.get_json()
                if not data or 'feedback' not in data:
                    return jsonify({'error': 'feedback text is required'}), 400
                feedback_text = data['feedback']
                classification_type = data.get('type', 'priority')  # priority, sentiment, scope
                prompt = self.build_classification_prompt(feedback_text, classification_type)
                response = self.generate_response(prompt)
                # Parse classification result
                classification = self.parse_classification_response(response, classification_type)
                return jsonify({
                    'classification': classification,
                    'confidence': 0.85,  # Placeholder - could be calculated
                    'raw_response': response
                })
            except Exception as e:
                logger.error(f"Error in classify_feedback: {e}")
                return jsonify({'error': str(e)}), 500
    def load_model(self):
        """Load the fine-tuned model and tokenizer."""
        try:
            logger.info("Mounting Google Drive...")
            drive.mount('/content/drive')
            logger.info(f"Loading model from: {self.model_path}")
            # Check if model exists
            if not os.path.exists(self.model_path):
                raise FileNotFoundError(f"Model not found at {self.model_path}")
            # Model configuration
            MODEL_ID = "meta-llama/Meta-Llama-3.1-8B-Instruct"
            # 4-bit quantization configuration
            bnb_config = BitsAndBytesConfig(
                load_in_4bit=True,
                bnb_4bit_quant_type="nf4",
                bnb_4bit_compute_dtype=torch.float16,
                bnb_4bit_use_double_quant=False,
            )
            # Load tokenizer
            logger.info("Loading tokenizer...")
            self.tokenizer = AutoTokenizer.from_pretrained(MODEL_ID)
            self.tokenizer.pad_token = self.tokenizer.eos_token
            self.tokenizer.padding_side = "right"
            # Load base model
            logger.info("Loading base model...")
            base_model = AutoModelForCausalLM.from_pretrained(
                MODEL_ID,
                quantization_config=bnb_config,
                device_map="auto",
                torch_dtype=torch.float16,
                trust_remote_code=True,
            )
            # Load PEFT model
            logger.info("Loading PEFT adapters...")
            self.model = PeftModel.from_pretrained(base_model, self.model_path)
            # Create pipeline
            logger.info("Creating inference pipeline...")
            self.pipe = pipeline(
                "text-generation",
                model=self.model,
                tokenizer=self.tokenizer,
                max_length=2048,
                temperature=0.7,
                do_sample=True,
                pad_token_id=self.tokenizer.eos_token_id,
                device_map="auto"
            )
            logger.info("✅ Model loaded successfully!")
            return True
        except Exception as e:
            logger.error(f"❌ Error loading model: {e}")
            return False
    def build_quaero_prompt(self, user_prompt: str, feedback_context: dict) -> str:
        """Build prompt with Quaero persona and feedback context."""
        # Extract context information
        total_feedback = feedback_context.get('total_feedback', 0)
        by_scope = feedback_context.get('by_scope', {})
        by_status = feedback_context.get('by_status', {})
        by_priority = feedback_context.get('by_priority', {})
        recent_feedback = feedback_context.get('recent_feedback', [])[:5]  # Limit to 5 recent items
        # Build system prompt
        system_prompt = f"""You are Quaero, an intelligent AI assistant for the Veritas University Feedback Management System.
You help administrators analyze and understand feedback data from students and staff.
Your personality:
- Professional yet approachable
- Data-driven and analytical
- Proactive in providing actionable insights
- Concise but thorough
- Specialized in Veritas University operations
Current feedback data context:
- Total feedback items: {total_feedback}
- Distribution by scope: {by_scope}
- Distribution by status: {by_status}
- Distribution by priority: {by_priority}
Recent feedback messages (for context):
{[{'scope': f['scope'], 'message': f['message'][:200], 'priority': f['priority'], 'status': f['status']} for f in recent_feedback]}
Respond to the administrator's query based on this data. Be specific with numbers and insights.
If asked about trends, patterns, or specific departments, analyze the data accordingly.
Keep responses concise (2-3 paragraphs max) unless more detail is requested.
Administrator's question: {user_prompt}"""
        # Format for Llama 3.1 chat template
        formatted_prompt = f"<|begin_of_text|><|start_header_id|>system<|end_header_id|>\\n\\n{system_prompt}<|eot_id|><|start_header_id|>user<|end_header_id|>\\n\\n{user_prompt}<|eot_id|><|start_header_id|>assistant<|end_header_id|>\\n\\n"
        return formatted_prompt
    def build_batch_prompt(self, feedback_item: dict, analysis_type: str) -> str:
        """Build prompt for batch analysis."""
        if analysis_type == "summary":
            instruction = f"Summarize this feedback and identify key issues: {feedback_item.get('message', '')}"
        elif analysis_type == "priority":
            instruction = f"What priority level should this feedback receive and why? {feedback_item.get('message', '')}"
        elif analysis_type == "sentiment":
            instruction = f"Analyze the sentiment of this feedback: {feedback_item.get('message', '')}"
        else:
            instruction = f"Analyze this feedback: {feedback_item.get('message', '')}"
        return f"<|begin_of_text|><|start_header_id|>user<|end_header_id|>\\n\\n{instruction}<|eot_id|><|start_header_id|>assistant<|end_header_id|>\\n\\n"
    def build_classification_prompt(self, feedback_text: str, classification_type: str) -> str:
        """Build prompt for classification tasks."""
        if classification_type == "priority":
            instruction = f"""Classify the priority level for this feedback as one of: low, normal, high, critical.
Feedback: "{feedback_text}"
Respond with just the priority level and a brief reason."""
        elif classification_type == "sentiment":
            instruction = f"""Classify the sentiment of this feedback as: positive, negative, or mixed.
Feedback: "{feedback_text}"
Respond with just the sentiment and a brief reason."""
        elif classification_type == "scope":
            instruction = f"""Classify which university department this feedback relates to. Common departments: Communication, Promotions & Offers, Returns & Refunds, Technical Support, Academic Services, Administrative Services.
Feedback: "{feedback_text}"
Respond with just the department and a brief reason."""
        else:
            instruction = f"Analyze this feedback: {feedback_text}"
        return f"<|begin_of_text|><|start_header_id|>user<|end_header_id|>\\n\\n{instruction}<|eot_id|><|start_header_id|>assistant<|end_header_id|>\\n\\n"
    def generate_response(self, prompt: str, max_new_tokens: int = 500) -> str:
        """Generate response using the model."""
        try:
            # Generate response
            response = self.pipe(
                prompt,
                max_new_tokens=max_new_tokens,
                do_sample=True,
                temperature=0.7,
                pad_token_id=self.tokenizer.eos_token_id
            )[0]['generated_text']
            # Extract just the assistant's response
            assistant_response = response.split('<|start_header_id|>assistant<|end_header_id|>\\n\\n')[-1].replace('<|eot_id|>', '')
            return assistant_response.strip()
        except Exception as e:
            logger.error(f"Error generating response: {e}")
            return f"I encountered an error while generating a response: {str(e)}"
    def parse_classification_response(self, response: str, classification_type: str) -> dict:
        """Parse classification response into structured format."""
        # Simple parsing - could be made more sophisticated
        lines = response.strip().split('\\n')
        if classification_type == "priority":
            # Extract priority level
            for line in lines:
                if any(priority in line.lower() for priority in ['low', 'normal', 'high', 'critical']):
                    for priority in ['critical', 'high', 'normal', 'low']:
                        if priority in line.lower():
                            return {'level': priority, 'reason': line}
        elif classification_type == "sentiment":
            # Extract sentiment
            for line in lines:
                if any(sentiment in line.lower() for sentiment in ['positive', 'negative', 'mixed']):
                    for sentiment in ['positive', 'negative', 'mixed']:
                        if sentiment in line.lower():
                            return {'sentiment': sentiment, 'reason': line}
        elif classification_type == "scope":
            # Extract department
            common_scopes = ['Communication', 'Promotions & Offers', 'Returns & Refunds', 'Technical Support', 'Academic Services', 'Administrative Services']
            for line in lines:
                for scope in common_scopes:
                    if scope.lower() in line.lower():
                        return {'scope': scope, 'reason': line}
        # Fallback
        return {'raw': response}
    def run(self, host: str = '0.0.0.0', port: int = 5000, debug: bool = False):
        """Run the Flask app."""
        logger.info(f"Starting Vuna Inference API on {host}:{port}")
        # Load model before starting server
        if not self.load_model():
            logger.error("Failed to load model. Exiting.")
            return
        # Run Flask app
        self.app.run(host=host, port=port, debug=debug)
