class DriftDetector:
    def __init__(self):
        pass
    def kolmogorov_smirnov(self, baseline_data: np.ndarray, new_data: np.ndarray) -> Tuple[float, float]:
        baseline_clean = baseline_data[~np.isnan(baseline_data)]
        new_clean = new_data[~np.isnan(new_data)]
        if len(baseline_clean) < 2 or len(new_clean) < 2:
            return 0.0, 1.0
        statistic, p_value = stats.ks_2samp(baseline_clean, new_clean)
        return statistic, p_value
    def population_stability_index(self, baseline_data: np.ndarray, new_data: np.ndarray, n_bins: int = 10) -> float:
        baseline_clean = baseline_data[~np.isnan(baseline_data)]
        new_clean = new_data[~np.isnan(new_data)]
        if len(baseline_clean) < 2 or len(new_clean) < 2:
            return 0.0
        min_val = min(np.min(baseline_clean), np.min(new_clean))
        max_val = max(np.max(baseline_clean), np.max(new_clean))
        if max_val == min_val:
            return 0.0
        bins = np.linspace(min_val, max_val, n_bins + 1)
        baseline_hist, _ = np.histogram(baseline_clean, bins=bins)
        new_hist, _ = np.histogram(new_clean, bins=bins)
        baseline_pct = baseline_hist / len(baseline_clean)
        new_pct = new_hist / len(new_clean)
        psi = 0.0
        for i in range(len(baseline_pct)):
            if baseline_pct[i] > 0:
