        baseline_clean = baseline_data[~np.isnan(baseline_data)]
        new_clean = new_data[~np.isnan(new_data)]
        if len(baseline_clean) == 0 or len(new_clean) == 0:
            return 0.0
        return float(wasserstein_distance(baseline_clean, new_clean))
    def compute_all(self, baseline_data: np.ndarray, new_data: np.ndarray) -> Dict[str, float]:
        results = {}
        results['ks_statistic'], results['ks_pvalue'] = self.kolmogorov_smirnov(baseline_data, new_data)
        results['psi'] = self.population_stability_index(baseline_data, new_data)
        results['wasserstein'] = self.wasserstein_distance_1d(baseline_data, new_data)
