class Baseline:
    def __init__(self):
        self.summaries = {}
        self.feature_names = []
        self.n_samples = 0
        self.n_features = 0
    def fit(self, data: np.ndarray, feature_names: Optional[List[str]] = None):
        if isinstance(data, list):
            data = np.array(data)
        if data.ndim == 1:
            data = data.reshape(-1, 1)
        self.n_samples, self.n_features = data.shape
        self.feature_names = feature_names if feature_names else [f"feature_{i}" for i in range(self.n_features)]
        for i, name in enumerate(self.feature_names):
            feature_data = data[:, i]
            self.summaries[name] = self._compute_summary(feature_data)
        return self
    def _compute_summary(self, data: np.ndarray) -> Dict:
        data_clean = data[~np.isnan(data)]
        if len(data_clean) == 0:
            return {
                'mean': 0.0,
                'std': 0.0,
                'min': 0.0,
                'max': 0.0,
                'quantiles': [0.0] * 5,
                'n_samples': 0
            }
        return {
            'mean': float(np.mean(data_clean)),
            'std': float(np.std(data_clean)),
            'min': float(np.min(data_clean)),
            'max': float(np.max(data_clean)),
            'quantiles': [float(q) for q in np.quantile(data_clean, [0.25, 0.5, 0.75, 0.95, 0.99])],
            'n_samples': int(len(data_clean))
        }
    def to_dict(self) -> Dict:
        return {
            'summaries': self.summaries,
            'feature_names': self.feature_names,
            'n_samples': self.n_samples,
            'n_features': self.n_features
        }
    def from_dict(self, data: Dict):
        self.summaries = data['summaries']
        self.feature_names = data['feature_names']
        self.n_samples = data['n_samples']
        self.n_features = data['n_features']
