class DriftMonitor:
    def __init__(self):
        self.baseline = Baseline()
        self.detector = DriftDetector()
        self.baseline_data = None
    def fit(self, data: Union[np.ndarray, List], feature_names: Optional[List[str]] = None):
        if isinstance(data, list):
            data = np.array(data)
        if data.ndim == 1:
            data = data.reshape(-1, 1)
        self.baseline_data = data.copy()
        self.baseline.fit(data, feature_names)
        return self
    def check(self, new_data: Union[np.ndarray, List], threshold_psi: float = 0.2, threshold_ks: float = 0.05) -> Dict:
        if isinstance(new_data, list):
            new_data = np.array(new_data)
        if new_data.ndim == 1:
            new_data = new_data.reshape(-1, 1)
        if new_data.shape[1] != self.baseline.n_features:
            raise ValueError(f"Expected {self.baseline.n_features} features, got {new_data.shape[1]}")
        results = {
            'drift_detected': False,
            'features': {},
            'overall_score': 0.0,
            'method_scores': {}
        }
        feature_scores = []
        method_scores = {'psi': [], 'ks_statistic': [], 'wasserstein': []}
        for i, feature_name in enumerate(self.baseline.feature_names):
            baseline_feature = self.baseline_data[:, i]
            new_feature = new_data[:, i]
            feature_results = self.detector.compute_all(baseline_feature, new_feature)
            psi_drift = feature_results['psi'] > threshold_psi
            ks_drift = feature_results['ks_pvalue'] < threshold_ks
            feature_drift = psi_drift or ks_drift
            feature_scores.append(float(feature_drift))
            method_scores['psi'].append(feature_results['psi'])
            method_scores['ks_statistic'].append(feature_results['ks_statistic'])
            method_scores['wasserstein'].append(feature_results['wasserstein'])
            results['features'][feature_name] = {
                'drift_detected': feature_drift,
                'psi': feature_results['psi'],
                'ks_statistic': feature_results['ks_statistic'],
                'ks_pvalue': feature_results['ks_pvalue'],
                'wasserstein': feature_results['wasserstein']
            }
            if feature_drift:
                results['drift_detected'] = True
        results['overall_score'] = float(np.mean(feature_scores))
        results['method_scores'] = {
            'psi_mean': float(np.mean(method_scores['psi'])),
            'ks_statistic_mean': float(np.mean(method_scores['ks_statistic'])),
            'wasserstein_mean': float(np.mean(method_scores['wasserstein']))
        }
        return results
    def check_with_metrics(self, new_data: Union[np.ndarray, List], threshold_psi: float = 0.2, threshold_ks: float = 0.05) -> Dict:
        tracemalloc.start()
        start_time = time.time()
        drift_results = self.check(new_data, threshold_psi, threshold_ks)
        end_time = time.time()
        current, peak = tracemalloc.get_traced_memory()
        tracemalloc.stop()
        latency_ms = (end_time - start_time) * 1000
        memory_mb = peak / (1024 * 1024)
        drift_results['metrics'] = {
            'latency_ms': latency_ms,
            'memory_mb': memory_mb
        }
        return drift_results
